export interface ReclassificationDeviceReportRequest {
  /**
   * Events whose uploads were permanently rejected.
   */
  failed: number;
  platform: Platform;
  /**
   * Events for which a higher revision was accepted (or already stored).
   */
  reclassified: number;
  /**
   * In-scope events the device still found locally and re-evaluated.
   */
  scanned: number;
  /**
   * Events whose locally re-computed interpretation already matched, including events a
   * manual Owner correction or a newer revision protects (stale_revision is a yield, not a
   * failure).
   */
  unchanged: number;
}

export interface ReclassificationEstimate {
  /**
   * One entry per device holding in-scope events, ordered by device identity.
   */
  devices: ReclassificationEstimateDevice[];
  /**
   * Instant the estimate was computed; a task freezes its own estimate at creation.
   */
  generated_at: string;
  /**
   * In-scope events across all devices.
   */
  total_events: number;
}

export interface ReclassificationEstimateDevice {
  /**
   * Server-bound device identity the in-scope events were uploaded with.
   */
  device_id: string;
  /**
   * Earliest observed start of this device's in-scope events.
   */
  earliest_start_at: null | string;
  /**
   * In-scope events uploaded by this device: finalized, non-AFK activity intervals below the
   * reserved manual-correction revision space. This is the frozen upper bound a task holds
   * this device accountable for; events beyond the device's local retention show up as
   * unrecoverable instead of being reclassified.
   */
  event_count: number;
  /**
   * Latest observed start of this device's in-scope events.
   */
  latest_start_at: null | string;
  /**
   * Collector platform the device reported its events with.
   */
  platform: Platform;
}

export interface ReclassificationTaskAssignment {
  /**
   * Inclusive UTC instant bounding the task scope; null means unbounded.
   */
  from: null | string;
  /**
   * Rule set version the device must cache before re-evaluating; a device that cannot fetch
   * this version defers the task instead of working with stale rules.
   */
  target_rule_set_version: number;
  task_id: string;
  /**
   * Exclusive UTC instant bounding the task scope; null means unbounded.
   */
  to: null | string;
}

export interface ReclassificationTaskCreateRequest {
  /**
   * Optional inclusive UTC instant bounding the task scope.
   */
  from?: string;
  /**
   * Rule set version devices must hold before re-evaluating. Defaults to the currently
   * published rule set version; a version above the published one is rejected because no
   * device could ever fetch it.
   */
  target_rule_set_version?: number;
  /**
   * Optional exclusive UTC instant bounding the task scope; must be later than from.
   */
  to?: string;
}

export interface ReclassificationTaskProgress {
  devices_reported: number;
  failed: number;
  reclassified: number;
  scanned: number;
  unchanged: number;
  /**
   * Sum of the per-device unrecoverable counts.
   */
  unrecoverable: number;
}

export interface ReclassificationTaskStatus {
  closed_at: null | string;
  created_at: string;
  /**
   * One entry per reporting device, ordered by device identity.
   */
  device_reports: ReclassificationDeviceReport[];
  estimate: ReclassificationEstimate;
  from: null | string;
  progress: ReclassificationTaskProgress;
  status: ReclassificationTaskStatusStatus;
  target_rule_set_version: number;
  task_id: string;
  to: null | string;
}

export type ReclassificationTaskStatusStatus = "open" | "closed";

export interface SourcePolicyDocument {
  entries: SourcePolicyEntry[];
  /**
   * Set on update responses: for each changed metric, the report-day ranges and normalized
   * result count the change affected. The same statement is appended to the audit log.
   */
  impact?: SourcePolicyImpact[];
  /**
   * When this version was written; null for the untouched default.
   */
  updated_at: null | string;
  /**
   * Monotonic policy version. Version 1 with the documented default priorities applies until
   * the Owner changes the policy.
   */
  version: number;
}

export interface SourcePolicyEntry {
  /**
   * Metric key with an explicit priority. Usage and payment metrics prioritize source kinds;
   * health metrics prioritize Health Connect data origins.
   */
  metric: string;
  /**
   * Source kinds or data origins from highest to lowest priority. The highest-priority source
   * with observations in a conflict window wins; an empty list means no explicit preference,
   * with all sources ranking deterministically by name. Competing observations are never
   * deleted.
   */
  priority: string[];
}

export interface SourcePolicyImpact {
  /**
   * Report-day ranges whose normalized selection differs between the old and new policy.
   * Empty when no stored observation competes differently.
   */
  affected_ranges: SourcePolicyImpactAffectedRange[];
  from_version: number;
  /**
   * Metric key whose priority changed.
   */
  metric: string;
  /**
   * Number of normalized day results the change affected.
   */
  result_count: number;
  /**
   * IANA report timezone the affected ranges resolve in, so the audit statement is
   * reproducible.
   */
  timezone: string;
  to_version: number;
}

export interface SourcePolicyImpactAffectedRange {
  from: string;
  to: string;
}

export interface SourcePolicyUpdateRequest {
  /**
   * Full replacement of the policy entries. Omitted metrics keep the default priority; a
   * policy change only rebuilds derived results and never modifies raw observations.
   */
  entries: SourcePolicyEntry[];
}

export interface UsageDayMetrics {
  active_minutes: number;
  /**
   * Local calendar day in the report timezone.
   */
  date: string;
  device_minutes: number;
}

export interface UsageDayReport {
  context: QueryContext;
  /**
   * The requested local calendar day.
   */
  date: string;
  /**
   * One entry per device lane contributing intervals to the day.
   */
  devices: UsageDeviceMetrics[];
  metrics: UsageMetrics;
  /**
   * IANA timezone the day boundaries resolved in.
   */
  timezone: string;
}

export interface UsageDeviceMetrics {
  /**
   * Deduplicated non-AFK time of this device lane; lane unions do not de-duplicate across
   * devices.
   */
  active_minutes: number;
  /**
   * Device lane identifier as reported in the event envelope.
   */
  device_id: string;
  /**
   * Device minutes attributed to this device lane.
   */
  device_minutes: number;
  platform: Platform;
}

export interface UsageMetrics {
  /**
   * Active minutes: the union of qualifying non-AFK intervals over the report range.
   * Overlapping or adjacent device time counts once.
   */
  active_minutes: number;
  /**
   * Device minutes: the sum of qualifying device intervals overlapping the report range
   * across all devices, including AFK foreground time. Concurrent device use can exceed
   * elapsed wall-clock time.
   */
  device_minutes: number;
}

export interface UsageWeekReport {
  context: QueryContext;
  /**
   * One entry per local day of the week, in order.
   */
  days: UsageDayMetrics[];
  metrics: UsageMetrics;
  /**
   * IANA timezone the week boundaries resolved in.
   */
  timezone: string;
  /**
   * Last local day of the Monday-start week in the report timezone.
   */
  week_end_date: string;
  /**
   * First local day of the Monday-start week in the report timezone.
   */
  week_start_date: string;
}
